def RNG(r):
    c, vv = r.split(':'); lo, hi = vv.split('-'); return int(c), int(lo), int(hi)
KINDS = []
for kind, first, rng, claim, cell, fields, effs, reuses in S.LINES:
    c, lo, hi = RNG(rng); en, he_en, extra, speaker, tape = KEN[kind]
    KINDS.append((kind, 'statute', en, HE(D, c, lo, hi, he_en), WIT(D, c, lo, hi) + [w for ws in extra for w in ws], INK, CORPUS, SUB % (speaker, tape), fields))
OWN21 = [k[0] for k in KINDS]
assert len(KINDS) == 21 and OWN21 == S.KINDS and all(len(k[8]) >= 2 for k in KINDS)
path = f"{ROOT}/World/step9/event_vocabulary.yaml"
text = open(path, encoding='utf-8').read()
have = yaml.safe_load(text)['events']
HOLEK = sorted(k for k in have if k in OWN21)
NEARK = sorted(k for k in have if k not in OWN21 and any(t in k for t in ('first_fruit', 'bikkur', 'tithe_confess', 'tithe_remov', 'covenant_formula', 'stones', 'ebal', 'gerizim', 'twelve_curses', 'amen', 'blessings_cond', 'curses_cond', 'storehouse', 'holy_people', 'heavens_treasure', 'brass', 'carcass', 'vineyard_king', 'harvests', 'iron_yoke', 'eagle', 'siege', 'plagues_scatter', 'ships')))
print('the registry\'s kinds among the twenty-one before this sitting:', HOLEK, '| the near kinds on file (not ours):', NEARK)
assert HOLEK == [] or HOLEK == sorted(OWN21), HOLEK   # the twenty-one kinds absent before this sitting — or this sitting's own, written by the first run (idempotent)
out = []
for name, form, en, he, wit, ink, corpus, tape, fields in KINDS:
    if name in have: continue
    out.append(f"  {name}:\n    en: {q(en)}\n    he: {q(he)}\n    form: {form}\n    witness: [{', '.join(q(w) for w in wit)}]\n    ink: {q(ink)}\n    corpus: {q(corpus)}\n    tape: {q(tape)}\n    fields: [{', '.join(q(f) for f in fields)}]\n")
if out and not CHECK:
    i = text.index('\nnarrative_verbs:\n')
    text = text[:i] + '\n' + ''.join(out).rstrip('\n') + text[i:]
    open(path, 'w', encoding='utf-8').write(text)
after = yaml.safe_load(open(path, encoding='utf-8'))
